package com.secure.documentwallet;

import android.content.*;import android.os.Bundle;import android.view.*;import android.widget.*;import androidx.fragment.app.FragmentActivity;import org.json.*;import java.util.*;import java.util.concurrent.*;

public class EmergencyAccessActivity extends FragmentActivity {
 private final ExecutorService io=Executors.newSingleThreadExecutor();private LinearLayout list;private final Set<String> selected=new HashSet<>();
 @Override public void onCreate(Bundle b){super.onCreate(b);Ui.safeScreen(this);Ui.lightBars(this);if(!Session.valid()){finish();return;}selected.addAll(getSharedPreferences("emergency-kit",0).getStringSet("documents",Collections.emptySet()));LinearLayout page=VaultPageUi.page(this);LinearLayout head=VaultPageUi.header(this,"Emergency Access Kit","Critical information when needed");head.addView(VaultPageUi.badge(this,"New"),new LinearLayout.LayoutParams(-2,Ui.dp(this,26)));page.addView(head);page.addView(VaultPageUi.notice(this,"✚","Protected Emergency Pack","Choose IDs, medical details, contacts, and insurance documents",0xfffff0ef,0xffc2413a));page.addView(VaultPageUi.sectionHead(this,"Included","Select essential items"));list=Ui.column(this);page.addView(list);TextView save=VaultPageUi.primary(this,"Configure Emergency Access");save.setBackground(Ui.bg(0xffc2413a,Ui.dp(this,13)));save.setOnClickListener(v->{getSharedPreferences("emergency-kit",0).edit().putStringSet("documents",new HashSet<>(selected)).apply();VaultActivityLog.add(this,"Emergency Kit Updated",selected.size()+" protected item"+(selected.size()==1?"":"s"));Ui.toast(this,"Emergency Kit Saved");});VaultPageUi.button(page,save);setContentView(VaultPageUi.screen(this,page,"profile"));load();}
 private void load(){io.execute(()->{try{JSONArray docs=new VaultRepository(this).all();runOnUiThread(()->render(docs));}catch(Exception e){runOnUiThread(()->Ui.toast(this,"Could Not Open Emergency Kit"));}});}
 private void render(JSONArray docs){list.removeAllViews();for(int i=docs.length()-1;i>=0;i--){JSONObject doc=docs.optJSONObject(i);if(doc==null)continue;String id=doc.optString("id");CheckBox check=new CheckBox(this);check.setText(doc.optString("title","Document")+"\n"+doc.optString("category","Document"));check.setTextSize(14);check.setTextColor(Ui.INK);check.setButtonTintList(android.content.res.ColorStateList.valueOf(0xffc2413a));check.setPadding(Ui.dp(this,12),Ui.dp(this,10),Ui.dp(this,12),Ui.dp(this,10));check.setBackground(Ui.stroke(Ui.SURFACE,Ui.dp(this,1),Ui.BORDER,Ui.dp(this,15)));check.setChecked(selected.contains(id));check.setOnCheckedChangeListener((v,on)->{if(on)selected.add(id);else selected.remove(id);});VaultPageUi.addRow(list,check);}if(docs.length()==0)list.addView(VaultPageUi.notice(this,"□","No Documents Yet","Add documents before building an emergency kit",Ui.SOFT,Ui.TEAL));}
 @Override protected void onDestroy(){super.onDestroy();io.shutdownNow();}
}
